style.css:
@-moz-document domain("chat.openai.com") {
body, .bg-token-surface-primary, .bg-token-surface-secondary {
    background-color: #fccfd6 !important;
    color: #ffffff !important;
  }

  /* Chat area background */
  .flex-1.overflow-hidden, .scrollbar-trigger, .react-scroll-to-bottom--css {
    background-color: #fccfd6 !important;
  }

  /* Sidebar background */
  .bg-token-surface-tertiary, .bg-gray-900, .bg-gray-800 {
    background-color: #fdd8de !important;
  }

  /* Text colors */
  .text-token-text-primary, .text-token-text-secondary, p, span, div {
    color: #ffffff !important;
  }

  /* Accent colors — buttons, highlights, links */
  button, .btn, .text-brand-green, .text-green-600, a {
    background-color: #ff9fba !important;
    color: #ffffff !important;
    border: none !important;
  }

  button:hover, .btn:hover {
    background-color: #ffb6c9 !important;
  }

  /* Message bubbles */
  .prose, .markdown {
    background: rgba(255, 255, 255, 0.15) !important;
    border-radius: 16px !important;
    padding: 10px !important;
  }

  /* Input box */
  textarea, .m-0, .w-full {
    background-color: #ffd6e1 !important;
    color: #ffffff !important;
    border: 1px solid #ffb3c8 !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar-thumb {
    background-color: #ffb6c9 !important;
    border-radius: 8px;
  }
}
